using Npgsql;using AvenChart.Api.Models;namespace AvenChart.Api.Data;
public sealed class RecallRepository(NpgsqlDataSource source){public async Task<IReadOnlyList<RecallItem>> GetAsync(CancellationToken ct){await using var c=await source.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText="select r.id,r.patient_id,p.last_name||', '||p.first_name,r.recall_date,r.reason,r.provider_id,r.facility_id,r.status,r.created_at from recalls r join patients p on p.canonical_id=r.patient_id where r.status='active' order by r.recall_date;";var x=new List<RecallItem>();await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))x.Add(new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetFieldValue<DateOnly>(3).ToString("yyyy-MM-dd"),r.GetString(4),r.IsDBNull(5)?null:r.GetInt32(5),r.IsDBNull(6)?null:r.GetInt32(6),r.GetString(7),r.GetFieldValue<DateTimeOffset>(8).ToString("O")));return x;}public async Task<RecallItem?> CreateAsync(RecallRequest x,CancellationToken ct){if(string.IsNullOrWhiteSpace(x.Reason))return null;await using var c=await source.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText="insert into recalls(id,patient_id,recall_date,reason,provider_id,facility_id,status) values(@id,@patient,@date,@reason,@provider,@facility,'active') returning id;";var id=Guid.NewGuid();q.Parameters.AddWithValue("id",id);q.Parameters.AddWithValue("patient",x.PatientId);q.Parameters.AddWithValue("date",x.RecallDate);q.Parameters.AddWithValue("reason",x.Reason.Trim());q.Parameters.AddWithValue("provider",(object?)x.ProviderId??DBNull.Value);q.Parameters.AddWithValue("facility",(object?)x.FacilityId??DBNull.Value);if(await q.ExecuteScalarAsync(ct)is null)return null;return (await GetAsync(ct)).FirstOrDefault(a=>a.Id==id);}public async Task<bool> DeleteAsync(Guid id,CancellationToken ct){await using var c=await source.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText="delete from recalls where id=@id;";q.Parameters.AddWithValue("id",id);return await q.ExecuteNonQueryAsync(ct)>0;}}
